\set ON_ERROR_STOP on
begin;
create function pg_temp.assert_true(ok boolean,label text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'FAIL: %',label; end if; raise notice 'PASS: %',label; end $$;
create function pg_temp.expect_error(sql text,expected text,label text) returns void language plpgsql as $$ begin begin execute sql; exception when others then if sqlerrm<>expected and sqlstate<>expected then raise exception 'FAIL: %, got %: %',label,sqlstate,sqlerrm; end if; raise notice 'PASS: %',label; return; end; raise exception 'FAIL: % succeeded',label; end $$;
insert into auth.users(id,email) values ('99999999-0000-0000-0000-000000000001','admin@test.invalid'),('99999999-0000-0000-0000-000000000002','front@test.invalid'),('99999999-0000-0000-0000-000000000003','qc@test.invalid');
insert into public.staff_profiles(id,display_name,role) values('99999999-0000-0000-0000-000000000001','Staff Admin','super_admin'),('99999999-0000-0000-0000-000000000002','Staff Front','front_office'),('99999999-0000-0000-0000-000000000003','Staff QC','warehouse_qc');
set local role authenticated;
select set_config('request.jwt.claim.sub','99999999-0000-0000-0000-000000000001',true);
select pg_temp.assert_true((public.list_staff(0,25)->>'total')::int=3,'Admin can list staff with Auth email');
select pg_temp.expect_error('select public.update_staff(gen_random_uuid(),''99999999-0000-0000-0000-000000000001'',1,''Admin'',''front_office'',true)','RG_STAFF_SELF','Self demotion cannot remove only admin');
select pg_temp.expect_error('select public.update_staff(gen_random_uuid(),''99999999-0000-0000-0000-000000000001'',1,''Admin'',''super_admin'',false)','RG_STAFF_SELF','Admin cannot disable own account');
select public.update_staff('99999999-9999-9999-9999-999999999991','99999999-0000-0000-0000-000000000002',1,'Edited Front','front_office',false);
select public.update_staff('99999999-9999-9999-9999-999999999991','99999999-0000-0000-0000-000000000002',1,'Edited Front','front_office',false);
select pg_temp.assert_true((select row_version=2 and not is_active from public.staff_profiles where id='99999999-0000-0000-0000-000000000002'),'Profile update and retry increment version once');
select pg_temp.expect_error('select public.update_staff(gen_random_uuid(),''99999999-0000-0000-0000-000000000002'',1,''Stale'',''front_office'',true)','RG_STAFF_VERSION','Stale admin edit rejected');
select public.staff_admin_prepare('99999999-9999-9999-9999-999999999992','create',null,'{"email":"new@test.invalid","display_name":"New Staff","role":"warehouse_qc","password":"DO_NOT_STORE"}');
reset role;
select pg_temp.assert_true(not (select payload?'password' from rantau_private.staff_requests where request_id='99999999-9999-9999-9999-999999999992'),'Creation ledger never stores password');
insert into auth.users(id,email,raw_app_meta_data) values('99999999-0000-0000-0000-000000000004','new@test.invalid','{"rantau_creation_request":"99999999-9999-9999-9999-999999999992","rantau_created_by":"99999999-0000-0000-0000-000000000001"}');
set local role authenticated;
select pg_temp.assert_true((public.staff_admin_prepare('99999999-9999-9999-9999-999999999992','create',null,'{"email":"new@test.invalid","display_name":"New Staff","role":"warehouse_qc"}')->>'user_id')::uuid='99999999-0000-0000-0000-000000000004','Retry recovers Auth user after lost create reply');
select pg_temp.expect_error('select public.staff_admin_finish(''99999999-9999-9999-9999-999999999992'',''99999999-0000-0000-0000-000000000001'')','42501','Desktop cannot call privileged finish');
reset role;
set local role service_role;
select public.staff_admin_finish('99999999-9999-9999-9999-999999999992','99999999-0000-0000-0000-000000000001');
select public.staff_admin_finish('99999999-9999-9999-9999-999999999992','99999999-0000-0000-0000-000000000001');
reset role;
select pg_temp.assert_true((select count(*)=1 from public.staff_profiles where id='99999999-0000-0000-0000-000000000004'),'Server finish creates profile once');
select pg_temp.assert_true((select count(*)=1 from public.audit_log where action='STAFF_CREATED'),'Creation audit recorded once without credentials');
set local role authenticated;
select pg_temp.expect_error('select public.staff_admin_prepare(gen_random_uuid(),''create'',null,''{"email":"admin@test.invalid","display_name":"Conflict","role":"front_office"}'')','RG_STAFF_EMAIL','Cannot attach an existing Auth email with different request marker');
select public.staff_admin_prepare('99999999-9999-9999-9999-999999999993','password','99999999-0000-0000-0000-000000000004','{}');
reset role;
set local role service_role;
select public.staff_admin_finish('99999999-9999-9999-9999-999999999993','99999999-0000-0000-0000-000000000001');
reset role;
select pg_temp.assert_true((select count(*)=1 from public.audit_log where action='PASSWORD_CHANGED'),'Password change audit has no password field');
set local role authenticated;
select set_config('request.jwt.claim.sub','99999999-0000-0000-0000-000000000002',true);
select pg_temp.expect_error('select public.list_staff(0,25)','42501','Inactive account cannot list staff');
select set_config('request.jwt.claim.sub','99999999-0000-0000-0000-000000000003',true);
select pg_temp.expect_error('select public.staff_admin_prepare(gen_random_uuid(),''password'',''99999999-0000-0000-0000-000000000004'',''{}'')','42501','QC cannot prepare password reset');
reset role;
select pg_temp.assert_true(not has_function_privilege('anon','public.list_staff(integer,integer)','execute'),'Anonymous staff list denied');
rollback;
